"""Write the OpenAPI spec generated by the app to apps/api/openapi.json.

Importing the app does not connect to the database, so this runs without one.
"""

import json
import sys
from pathlib import Path

API_ROOT = Path(__file__).resolve().parents[1] / "apps" / "api"
sys.path.insert(0, str(API_ROOT))

from app.main import app  # noqa: E402

target = API_ROOT / "openapi.json"
target.write_text(json.dumps(app.openapi(), indent=2, sort_keys=True) + "\n")
print(f"Wrote {target}")
